function EventForm({ value }) {
  const { state, act, run, setModal, setCompose, setTab, openMessage } = useMail();
  const defaults = { title: "", start: DateTime.now().setZone("Asia/Hong_Kong").plus({ hours: 1 }).startOf("hour").toISO(), end: DateTime.now().setZone("Asia/Hong_Kong").plus({ hours: 2 }).startOf("hour").toISO(), timeZone: "Asia/Hong_Kong", calendarId: "default", reminderMinutes: 15, description: "", location: "", rrule: "", color: "" };
  const [form, setForm] = useState({ ...defaults, ...value }), [attendees, setAttendees] = useState(addr(value?.attendees)), [accountId, setAccountId] = useState(state.accounts.find((a) => !a.local)?.id || "");
  const change = (key, v) => setForm({ ...form, [key]: v });
  const time = (key) => form.allDay ? form[key]?.slice(0, 10) : DateTime.fromISO(form[key], { zone: form.timeZone }).toFormat("yyyy-MM-dd'T'HH:mm");
  const save = () => act({ action: "events.save", event: form });
  return <form className="dm-form" onSubmit={(e) => { e.preventDefault(); run(async () => { await save(); setModal(null); }); }}>{form.recurrenceId && <div className="dm-notice">正在编辑本次重复事件，其他日期保持原安排。</div>}<Field label="事件名称" required value={form.title} onChange={(e) => change("title", e.target.value)} /><div className="dm-form-grid"><Field label="开始" type={form.allDay ? "date" : "datetime-local"} value={time("start")} onChange={(e) => change("start", e.target.value)} required /><Field label={form.allDay ? "结束（不包含当天）" : "结束"} type={form.allDay ? "date" : "datetime-local"} value={time("end")} onChange={(e) => change("end", e.target.value)} required /><Field label="时区" value={form.timeZone} onChange={(e) => change("timeZone", e.target.value)} /><Field label="日历"><select value={form.calendarId} onChange={(e) => change("calendarId", e.target.value)}>{state.calendars.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="提前提醒（分钟）" type="number" min="0" value={form.reminderMinutes} onChange={(e) => change("reminderMinutes", Number(e.target.value))} /><Field label="重复"><select value={["", "FREQ=DAILY", "FREQ=WEEKLY", "FREQ=MONTHLY", "FREQ=YEARLY"].includes(form.rrule) ? form.rrule : "custom"} onChange={(e) => change("rrule", e.target.value === "custom" ? "FREQ=WEEKLY;COUNT=10" : e.target.value)}>{[["", "不重复"], ["FREQ=DAILY", "每天"], ["FREQ=WEEKLY", "每周"], ["FREQ=MONTHLY", "每月"], ["FREQ=YEARLY", "每年"], ["custom", "自定义规则"]].map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></Field></div><fieldset className="dm-event-colors"><legend>事件颜色</legend><div className="dm-color-options"><Button aria-pressed={!form.color} onClick={() => change("color", "")}>跟随日历颜色</Button>{EVENT_COLORS.map(([name, color]) => <Button key={color} className="dm-color-swatch" aria-label={`事件颜色：${name}`} aria-pressed={form.color === color} title={name} style={{ backgroundColor: color, color: "#ffffff" }} onClick={() => change("color", color)}>{form.color === color ? "✓" : ""}</Button>)}<Field label="自定义颜色" type="color" value={eventAppearance(form, state.calendars).backgroundColor} onInput={(e) => change("color", e.target.value)} onChange={(e) => change("color", e.target.value)} /></div><span className="dm-muted">{form.color ? `此事件使用 ${form.color}` : "使用所属日历的颜色"}</span></fieldset><label><input type="checkbox" checked={!!form.allDay} onChange={(e) => { const allDay = e.target.checked, start = DateTime.fromISO(form.start, { zone: form.timeZone }), end = DateTime.fromISO(form.end, { zone: form.timeZone }); setForm({ ...form, allDay, ...(allDay ? { start: start.toISODate(), end: (end.startOf("day") > start.startOf("day") ? end : start.plus({ days: 1 })).toISODate() } : {}) }); }} />全天事件</label>{form.rrule && <Field label="重复规则（RRULE）" value={form.rrule} onChange={(e) => change("rrule", e.target.value)} />}<Field label="地点" value={form.location} onChange={(e) => change("location", e.target.value)} /><Field label="备注"><textarea value={form.description} onChange={(e) => change("description", e.target.value)} /></Field>{form.sourceMessageId && <Button onClick={() => { openMessage(form.sourceMessageId); setModal(null); }}>查看来源邮件 ↗</Button>}
    <details><summary>会议邀请与回复</summary><Field label="发件账号"><select value={accountId} onChange={(e) => setAccountId(e.target.value)}>{state.accounts.filter((a) => !a.local).map((a) => <option key={a.id} value={a.id}>{a.email}</option>)}</select></Field><Field label="邀请对象" value={attendees} onChange={(e) => setAttendees(e.target.value)} placeholder="email@example.com" /><Button onClick={() => run(async () => { const event = await save(); const draft = await act({ action: "events.invite", id: event.id, accountId, attendees: attendees.split(/[,;]/).filter(Boolean).map((s) => ({ address: s.trim() })) }); setModal(null); setCompose(draft); setTab("邮件"); })}>准备邀请邮件</Button>{form.organizer && <div className="dm-inline">{[["ACCEPTED", "接受"], ["TENTATIVE", "暂定"], ["DECLINED", "拒绝"]].map(([response, label]) => <Button key={response} onClick={() => run(async () => { const draft = await act({ action: "events.rsvp", id: form.id, accountId, response }); setModal(null); setCompose(draft); setTab("邮件"); })}>{label}并准备回复</Button>)}</div>}</details><footer><button className="primary" type="submit">保存事件</button>{form.seriesId && <Button onClick={() => setForm(state.events.find((e) => e.id === form.seriesId))}>编辑整组重复事件</Button>}{(form.id || form.recurrenceId) && <Button danger onClick={() => run(async () => { await act(form.id ? { action: "events.delete", id: form.id } : { action: "events.save", event: { ...form, status: "CANCELLED" } }); setModal(null); })}>删除本地事件</Button>}</footer></form>;
}

function TasksView() {
  const { state, act, run, setModal, openMessage } = useMail(), [filter, setFilter] = useState("open");
  const tasks = state.tasks.filter((t) => filter === "all" || (filter === "done" ? t.done : !t.done)).sort((a, b) => (a.due || "9999").localeCompare(b.due || "9999"));
  return <section className="dm-page"><header className="dm-page-heading"><div><h2>待办</h2><p>记下下一步，让重要邮件有着落。</p></div><Button primary onClick={() => setModal({ type: "task" })}>＋ 新待办</Button></header><div className="dm-tabs">{[["open", "未完成"], ["done", "已完成"], ["all", "全部"]].map(([key, label]) => <Button key={key} aria-pressed={filter === key} onClick={() => setFilter(key)}>{label}</Button>)}</div>{!tasks.length && <Empty icon="✓" title="没有待办事项">从邮件提取任务，或添加自己的安排。</Empty>}{tasks.map((task) => <article key={task.id} className="dm-task-row"><input type="checkbox" aria-label={`完成 ${task.title}`} checked={!!task.done} onChange={(e) => run(() => act({ action: "resources.save", kind: "tasks", value: { ...task, done: e.target.checked } }))} /><button className="dm-task-title" onClick={() => setModal({ type: "task", value: task })}><strong>{task.title}</strong><small>{task.due ? date(task.due) : "未设置截止日期"} · {({ high: "高优先级", normal: "普通", low: "低优先级" })[task.priority || "normal"]}</small></button>{task.sourceMessageId && <Button onClick={() => openMessage(task.sourceMessageId)}>来源邮件</Button>}<Button onClick={() => setModal({ type: "event", value: { title: task.title, sourceMessageId: task.sourceMessageId, description: task.evidence || "" } })}>安排时间</Button></article>)}</section>;
}
function TaskForm({ value }) {
  const { act, run, setModal } = useMail(), [form, setForm] = useState({ title: "", priority: "normal", evidence: "", ...value });
  return <form className="dm-form" onSubmit={(e) => { e.preventDefault(); run(async () => { await act({ action: "resources.save", kind: "tasks", value: form }); setModal(null); }); }}><Field label="事项" required value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} /><div className="dm-form-grid"><Field label="截止日期" type="datetime-local" value={form.due ? DateTime.fromISO(form.due).toFormat("yyyy-MM-dd'T'HH:mm") : ""} onChange={(e) => setForm({ ...form, due: e.target.value ? new Date(e.target.value).toISOString() : null })} /><Field label="优先级"><select value={form.priority} onChange={(e) => setForm({ ...form, priority: e.target.value })}><option value="high">高</option><option value="normal">普通</option><option value="low">低</option></select></Field></div><Field label="备注 / 邮件依据"><textarea value={form.evidence} onChange={(e) => setForm({ ...form, evidence: e.target.value })} /></Field><footer><button className="primary" type="submit">保存待办</button>{form.id && <Button danger onClick={() => run(async () => { await act({ action: "resources.delete", kind: "tasks", id: form.id }); setModal(null); })}>删除</Button>}</footer></form>;
}

function ContactsView() {
  const { state, setModal, setQuery, setTab, act, run, download } = useMail(), [search, setSearch] = useState(""); const contacts = state.contacts.filter((c) => `${c.name} ${c.email} ${c.group}`.toLowerCase().includes(search.toLowerCase()));
  return <section className="dm-page"><header className="dm-page-heading"><div><h2>联系人</h2><p>账号中的往来，与本机通讯录集中管理。</p></div><Button primary onClick={() => setModal({ type: "contact" })}>＋ 联系人</Button></header><input className="dm-wide-search" aria-label="搜索联系人" placeholder="搜索姓名、邮箱或分组" value={search} onChange={(e) => setSearch(e.target.value)} />{!contacts.length && <Empty icon="♙" title="通讯录还是空的">添加联系人，或导入 CSV / vCard。</Empty>}<div className="dm-contact-grid">{contacts.map((c) => <article className="dm-contact" key={c.id}><span className="dm-avatar">{(c.name || c.email).slice(0, 1).toUpperCase()}</span><h3>{c.name || c.email}</h3><p>{c.email}</p><small>{c.group || "未分组"}</small><footer><Button onClick={() => setModal({ type: "contact", value: c })}>编辑</Button><Button onClick={() => { setQuery({ from: c.email }); setTab("邮件"); }}>往来邮件</Button></footer></article>)}</div><footer className="dm-inline"><label className="dm-file-button">导入 CSV / vCard<input type="file" accept=".csv,.vcf" onChange={(e) => run(async () => { const f = e.target.files[0]; if (f) await act({ action: "contacts.import", text: await f.text(), format: f.name.endsWith(".vcf") ? "vcard" : "csv" }, "联系人导入已完成，请查看结果"); })} /></label><Button onClick={() => download({ action: "contacts.export", format: "csv" })}>导出 CSV</Button><Button onClick={() => download({ action: "contacts.export", format: "vcard" })}>导出 vCard</Button></footer></section>;
}
function ContactForm({ value }) { const { act, run, setModal } = useMail(), [form, setForm] = useState({ name: "", email: "", group: "", ...value }); return <form className="dm-form" onSubmit={(e) => { e.preventDefault(); run(async () => { await act({ action: "resources.save", kind: "contacts", value: form }); setModal(null); }); }}>{[["name", "姓名"], ["email", "邮箱"], ["group", "分组"]].map(([key, label]) => <Field key={key} label={label} required={key === "email"} type={key === "email" ? "email" : "text"} value={form[key]} onChange={(e) => setForm({ ...form, [key]: e.target.value })} />)}<footer><button className="primary" type="submit">保存联系人</button>{form.id && <Button danger onClick={() => run(async () => { await act({ action: "resources.delete", kind: "contacts", id: form.id }); setModal(null); })}>删除</Button>}</footer></form>; }

function RulesView() { const { state, act, run, setModal } = useMail(); return <section className="dm-page"><header className="dm-page-heading"><div><h2>规则与过滤器</h2><p>规则在本机运行，启用后应用于新同步的邮件。</p></div><Button primary onClick={() => setModal({ type: "rule" })}>＋ 新规则</Button></header>{!state.rules.length && <Empty icon="☷" title="把重复整理交给规则">按发件人、主题或正文匹配，自动加星、移动和创建待办。也可以让 AI 帮你准备规则。</Empty>}{state.rules.sort((a, b) => a.priority - b.priority).map((rule) => <article className="dm-rule-row" key={rule.id}><label><input type="checkbox" role="switch" aria-label={`启用 ${rule.name}`} checked={rule.enabled} onChange={(e) => run(() => act({ action: "rules.enable", id: rule.id, enabled: e.target.checked }))} /></label><div><h3>{rule.name}</h3><p>{rule.conditions.length} 个条件 · {rule.match === "any" ? "满足任一" : "全部满足"} · {rule.actions.map((a) => ({ star: "星标", read: "已读", label: "标签", move: "移动", archive: "归档", task: "待办" })[a.action]).join(" → ")}</p><small>{rule.enabled ? "已启用" : "已停用"} · 优先级 {rule.priority}</small></div><Button onClick={() => setModal({ type: "rule", value: rule })}>编辑</Button><Button onClick={() => run(async () => setModal({ type: "preview", value: await act({ action: "rules.apply", id: rule.id }) }))}>应用于历史邮件…</Button></article>)}</section>; }
function RuleForm({ value }) {
  const { state, act, run, setModal } = useMail(), [form, setForm] = useState(value || { name: "", match: "all", conditions: [{ field: "from", operator: "contains", value: "" }], actions: [{ action: "star", value: true }], priority: 0 }), [preview, setPreview] = useState(null);
  const edit = (group, index, patch) => setForm({ ...form, [group]: form[group].map((x, i) => i === index ? { ...x, ...patch } : x) });
  return <form className="dm-form" onSubmit={(e) => { e.preventDefault(); run(async () => { await act({ action: "rules.save", rule: form }, "规则已保存为停用状态；核对后再启用"); setModal(null); }); }}><Field label="规则名称" required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /><div className="dm-form-grid"><Field label="作用账号"><select value={form.accountId || ""} onChange={(e) => setForm({ ...form, accountId: e.target.value })}><option value="">全部账号</option>{state.accounts.map((a) => <option key={a.id} value={a.id}>{a.name}</option>)}</select></Field><Field label="匹配条件"><select value={form.match} onChange={(e) => setForm({ ...form, match: e.target.value })}><option value="all">全部满足</option><option value="any">满足任一</option></select></Field></div><h3>如果邮件符合</h3>{form.conditions.map((c, i) => <div className="dm-rule-editor-row" key={i}><select aria-label={`条件 ${i + 1} 字段`} value={c.field} onChange={(e) => edit("conditions", i, { field: e.target.value })}>{[["from", "发件人"], ["to", "收件人"], ["subject", "主题"], ["text", "正文"], ["hasAttachment", "有附件"], ["seen", "已读"], ["starred", "星标"]].map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select><select aria-label={`条件 ${i + 1} 比较`} value={c.operator} onChange={(e) => edit("conditions", i, { operator: e.target.value })}>{[["contains", "包含"], ["equals", "等于"], ["notContains", "不包含"], ["endsWith", "结尾为"]].map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select><input aria-label={`条件 ${i + 1} 内容`} required value={c.value} onChange={(e) => edit("conditions", i, { value: e.target.value })} /><Button onClick={() => setForm({ ...form, conditions: form.conditions.filter((_, n) => n !== i) })}>×</Button></div>)}<Button onClick={() => setForm({ ...form, conditions: [...form.conditions, { field: "subject", operator: "contains", value: "" }] })}>＋ 条件</Button><h3>按顺序执行</h3>{form.actions.map((a, i) => <div className="dm-rule-editor-row" key={i}><select aria-label={`动作 ${i + 1}`} value={a.action} onChange={(e) => edit("actions", i, { action: e.target.value, value: e.target.value === "label" ? [] : true })}>{[["star", "添加星标"], ["read", "标为已读"], ["label", "本地标签"], ["move", "移动到文件夹"], ["archive", "归档"], ["task", "创建本地待办"]].map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select>{a.action === "move" ? <select aria-label="规则目标文件夹" value={a.destinationId || ""} onChange={(e) => edit("actions", i, { destinationId: e.target.value })}><option value="">请选择文件夹</option>{state.folders.map((f) => <option key={f.id} value={f.id}>{f.path}</option>)}</select> : a.action === "label" ? <input aria-label="规则标签" value={Array.isArray(a.value) ? a.value.join(",") : ""} onChange={(e) => edit("actions", i, { value: e.target.value.split(/[,，]/).filter(Boolean) })} /> : a.action === "task" ? <input aria-label="规则待办标题" placeholder="留空使用邮件主题" value={a.title || ""} onChange={(e) => edit("actions", i, { title: e.target.value })} /> : null}<Button onClick={() => setForm({ ...form, actions: form.actions.filter((_, n) => n !== i) })}>×</Button></div>)}<Button onClick={() => setForm({ ...form, actions: [...form.actions, { action: "read", value: true }] })}>＋ 动作</Button><Field label="优先级（越小越先执行）" type="number" value={form.priority} onChange={(e) => setForm({ ...form, priority: Number(e.target.value) })} /><label><input type="checkbox" checked={!!form.stop} onChange={(e) => setForm({ ...form, stop: e.target.checked })} />命中后停止其他规则</label>{preview && <div className="dm-notice"><p>当前命中 {preview.count} 封</p>{preview.samples.map((m) => <p key={m.id}>{m.subject}</p>)}</div>}<footer><Button onClick={() => run(async () => setPreview(await act({ action: "rules.preview", rule: form })))}>预览命中</Button><button className="primary" type="submit">保存规则</button></footer></form>;
}

function SettingsView() {
  const { state, setModal, act, run, download } = useMail();
  return <section className="dm-page"><header className="dm-page-heading"><div><h2>设置</h2><p>本机邮箱、数据和日常偏好。</p></div><Button primary onClick={() => setModal({ type: "account" })}>＋ 添加邮箱</Button></header><h3>邮箱账号</h3>{state.accounts.filter((a) => !a.local).map((a) => <article className="dm-account-row" key={a.id}><span className="dm-avatar">@</span><div><strong>{a.name}</strong><p>{a.email}</p><small>{statusText[a.status] || "等待同步"} · {a.lastSyncedAt ? `上次同步 ${date(a.lastSyncedAt)}` : "尚未完成同步"}</small>{a.error && <p className="dm-error-text">{a.error.message}</p>}</div><Button onClick={() => setModal({ type: "account", value: a })}>配置</Button><Button onClick={() => run(() => act({ action: "sync", accountId: a.id }))}>重试同步</Button><Button onClick={() => run(() => act({ action: "accounts.remove", id: a.id }, "账号已断开，缓存邮件保留"))}>断开连接</Button></article>)}{!state.accounts.length && <p className="dm-muted">还没有连接邮箱。163 请使用客户端授权码。</p>}
    <h3>签名与模板</h3>{[["signatures", "签名"], ["templates", "模板"]].map(([kind, label]) => <div key={kind} className="dm-settings-group"><div className="dm-section-label">{label}<Button onClick={() => setModal({ type: "resource", kind, value: { name: "", text: "", subject: "" }, title: `编辑${label}` })}>＋ 新{label}</Button></div>{state[kind].map((v) => <button key={v.id} className="dm-settings-item" onClick={() => setModal({ type: "resource", kind, value: v, title: `编辑${label}` })}>{v.name} →</button>)}</div>)}
    <h3>导入、备份与恢复</h3><div className="dm-settings-card"><p>EML / MBOX 导入本地归档。备份包含本地邮件、规则、日历与待办，不包含授权码。</p><div className="dm-inline"><label className="dm-file-button">导入邮件<input type="file" accept=".eml,.mbox" onChange={(e) => run(async () => { const file = e.target.files[0]; if (file) await act({ action: "mail.import", ...await fileData(file), format: file.name.endsWith(".mbox") ? "mbox" : "eml" }, "邮件已导入本地归档"); })} /></label><Button onClick={() => download({ action: "backup.create" })}>导出完整备份</Button><label className="dm-file-button">恢复备份<input type="file" accept=".zip" onChange={(e) => run(async () => { const file = e.target.files[0]; if (file) await act({ action: "backup.restore", ...await fileData(file) }, "备份已恢复，请重新连接账号"); })} /></label></div><p className="dm-muted">恢复仅允许写入空数据配置；现有邮箱不会被覆盖。数据迁移后规则保持停用，草稿不会自动发送。</p></div>
    <h3>运行边界</h3><div className="dm-settings-card"><p>DSH 完全退出后，同步、规则、提醒及定时发送暂停。错过时间的发送需要重新确认。</p><p>AI 使用当前 DSH 会话的模型。只有你请求分析的相关邮件内容才进入模型上下文。</p><p>打开追踪使用收件人客户端提供的已读回执；没有回执显示“未知”。</p><p>DSH Mail {state.version} · <a href="https://github.com/xiaoxinblast/dsh-mail" target="_blank" rel="noreferrer">GitHub 与更新说明 ↗</a></p></div></section>;
}
function ResourceForm({ kind, value }) { const { act, run, setModal } = useMail(), [form, setForm] = useState(value); return <form className="dm-form" onSubmit={(e) => { e.preventDefault(); run(async () => { if (kind === "labels" && form.messageId) await act({ action: "messages.action", ids: [form.messageId], operation: "label", value: form.name.split(/[,，]/).filter(Boolean) }); else await act({ action: "resources.save", kind, value: form }); if (kind === "labels" && form.messageId) for (const name of form.name.split(/[,，]/).filter(Boolean)) await act({ action: "resources.save", kind: "labels", value: { name, color: form.color || "#155e75" } }); setModal(null); }); }}><Field label={kind === "labels" ? "本地标签（逗号分隔）" : "名称"} required value={form.name || ""} onChange={(e) => setForm({ ...form, name: e.target.value })} />{["calendars", "labels"].includes(kind) && <Field label="颜色" type="color" value={form.color || "#155e75"} onChange={(e) => setForm({ ...form, color: e.target.value })} />}{kind === "templates" && <Field label="邮件主题" value={form.subject || ""} onChange={(e) => setForm({ ...form, subject: e.target.value })} />}{["signatures", "templates"].includes(kind) && <Field label="内容"><textarea value={form.text || ""} onChange={(e) => setForm({ ...form, text: e.target.value })} /></Field>}<footer><button className="primary" type="submit">保存</button>{form.id && <Button danger onClick={() => run(async () => { await act({ action: "resources.delete", kind, id: form.id }); setModal(null); })}>删除</Button>}</footer></form>; }
function Activity() { const { state, act, run, setModal, openMessage } = useMail(); return <div className="dm-form"><h3>待确认</h3>{state.previews.map((p) => <Button key={p.id} onClick={() => setModal({ type: "preview", value: p })}>{p.kind === "send" ? p.details.subject || "发送邮件" : `${p.kind} · ${p.details.count} 项`} →</Button>)}<h3>提醒</h3>{state.notifications.map((n) => <div className="dm-activity-row" key={n.id}><span>{n.title}<small>{date(n.createdAt)}</small></span><Button onClick={() => run(() => act({ action: "notifications.dismiss", id: n.id }))}>已知晓</Button></div>)}<h3>操作任务</h3>{state.jobs.map((j) => <details key={j.id}><summary>{j.kind} · {j.status} · {j.completed}/{j.items.length}</summary>{j.items.filter((x) => x.error || x.result?.unknown || x.copies?.some((c) => c.status === "unknown")).map((x) => <div key={x.id}><p>{x.error?.message || x.result?.message || "存在结果待核查的复制"}</p>{x.copies?.filter((c) => c.status === "unknown").map((c) => <p key={c.id}>{c.id}：{c.error?.message || c.result?.message || "状态未知，请核查目标"}</p>)}</div>)}{["running", "queued"].includes(j.status) && <Button onClick={() => run(() => act({ action: "jobs.cancel", id: j.id }))}>取消</Button>}{["partial", "interrupted"].includes(j.status) && <Button onClick={() => run(() => act({ action: "jobs.retry", id: j.id }))}>重试安全的未完成项</Button>}</details>)}<h3>操作记录</h3>{state.logs.slice(0, 30).map((l) => <div className="dm-activity-row" key={l.id}><span>{l.kind}</span><small>{date(l.time)}</small>{l.data.message && <p>{l.data.message}</p>}</div>)}</div>; }
function AttachmentPreview({ value }) { const supportedImage = /^image\/(png|jpeg|gif|webp)$/.test(value.contentType), isPdf = value.contentType === "application/pdf"; return <div className="dm-form"><p>{value.filename}</p>{supportedImage ? <img className="dm-image-preview" src={`data:${value.contentType};base64,${value.base64}`} alt={value.filename} /> : isPdf ? <iframe className="dm-pdf-preview" title={value.filename} sandbox="" src={`data:application/pdf;base64,${value.base64}`} /> : <p>此类型不在应用内预览，请保存后用对应应用打开。</p>}<Button primary onClick={() => deliverFile(value)}>下载文件</Button></div>; }
